(() => {
  const CARD_VERSION = "0.1.0-beta.25";
  const STARLINE_ASSETS = {"bg_guard":"data:image/png;base64,","bg_guard_dark":"data:image/png;base64,","door":"data:image/png;base64,","door_dark":"data:image/png;base64,","hood":"data:image/png;base64,","hood_dark":"data:image/png;base64,","trunk":"data:image/png;base64,","trunk_dark":"data:image/png;base64,","frontlight":"data:image/png;base64,","frontlight_dark":"data:image/png;base64,","key":"data:image/png;base64,","key_dark":"data:image/png;base64,","sectors_1":"data:image/png;base64,","sectors_1_dark":"data:image/png;base64,","sectors_2":"data:image/png;base64,","sectors_2_dark":"data:image/png;base64,","sectors_3":"data:image/png;base64,","sectors_3_dark":"data:image/png;base64,","smoke_1":"data:image/png;base64,","smoke_1_dark":"data:image/png;base64,","smoke_2":"data:image/png;base64,","smoke_2_dark":"data:image/png;base64,","smoke_3":"data:image/png;base64,","smoke_3_dark":"data:image/png;base64,"};
  const INTEGRATION = "gwm_ru";
  const DEFAULT_CONTROLS = ["engine", "lock", "climate", "trunk", "refresh", "seat_heating"];
  const DEFAULT_INFO = [];
  const DEFAULT_STATUSES = ["engine", "climate", "fuel", "mileage", "doors", "windows", "trunk", "lock"];

  const CONTROL_OPTIONS = [
    ["seat_heating", "Подогрев обоих сидений"],
    ["lock", "Центральный замок"],
    ["engine", "Двигатель"],
    ["climate", "Климат"],
    ["trunk", "Багажник"],
    ["windows", "Окна"],
    ["refresh", "Обновление данных"],
    ["steering", "Обогрев руля"],
    ["rear_defrost", "Обогрев заднего стекла"],
    ["front_defrost", "Передний defrost"],
    ["sunroof", "Панорамная крыша / люк"],
    ["sunshade", "Шторка панорамной крыши"],
  ];

  const INFO_OPTIONS = [
    ["fuel", "Топливо"],
    ["range", "Запас хода"],
    ["mileage", "Пробег"],
    ["tires", "Давление шин"],
    ["gsm", "GSM / T-Box"],
    ["gps", "GPS"],
    ["climate", "Климат"],
    ["oil", "Уровень масла GWM"],
    ["update", "Последнее обновление"],
  ];

  const STATUS_OPTIONS = [
    ["engine", "Двигатель"],
    ["climate", "Климат"],
    ["fuel", "Топливо"],
    ["mileage", "Пробег"],
    ["doors", "Двери"],
    ["windows", "Окна"],
    ["trunk", "Багажник"],
    ["lock", "Замок"],
    ["defrost", "Defrost"],
  ];

  const SUFFIX = {
    seatDriver: "_driver_seat_heater_state",
    seatPassenger: "_passenger_seat_heater_state",
    engine: "_engine_on",
    doors: "_doors_open",
    doorFl: "_door_fl_open",
    doorFr: "_door_fr_open",
    doorRl: "_door_rl_open",
    doorRr: "_door_rr_open",
    windows: "_windows_open",
    window1: "_window_fr_open",
    window1Raw: "_window_2210001_raw",
    window2: "_window_fl_open",
    window2Raw: "_window_2210002_raw",
    window3: "_window_rr_open",
    window3Raw: "_window_2210003_raw",
    window4: "_window_rl_open",
    window4Raw: "_window_2210004_raw",
    trunk: "_trunk_open",
    unlocked: "_locked",
    climateOn: "_climate_on",
    tbox: "_tbox_online",
    gps: "_gps_enabled",
    lock: "_central_lock",
    climate: "_climate",
    refresh: "_refresh",
    fuel: "_fuel_liters",
    fuelPercent: "_fuel_percent",
    range: "_range_km",
    mileage: "_mileage_total",
    modelCode: "_model_code_raw",
    oilQty: "_oil_qty",
    lastUpdate: "_last_successful_update",
    tireFlP: "_tire_fl_pressure",
    tireFrP: "_tire_fr_pressure",
    tireRlP: "_tire_rl_pressure",
    tireRrP: "_tire_rr_pressure",
    signal: "_tbox_signal_raw",
    lastCommand: "_last_command",
    featureFlags: "_feature_flags",
    steeringHeat: "_steering_wheel_heater_on",
    rearDefrost: "_rear_defroster_on",
    frontDefrost: "_front_defrost_on",
    sunroofOpen: "_sunroof_open",
    light7Raw: "_light_2204007_raw",
    light8Raw: "_light_2204008_raw",
  };

  const FEATURE_BY_CONTROL = {
    steering: "steering_wheel_heat",
    rear_defrost: "rear_defrost",
    front_defrost: "front_defrost",
    sunroof: "sunroof",
    sunshade: "sunshade",
  };

  class GwmVehicleRemoteCardEditor extends HTMLElement {
    constructor() {
      super();
      this.attachShadow({ mode: "open" });
      this._config = {};
    }

    set hass(hass) {
      this._hass = hass;
    }

    setConfig(config) {
      this._config = {
        controls: [...DEFAULT_CONTROLS],
        info: [...DEFAULT_INFO],
        statuses: [...DEFAULT_STATUSES],
        confirm_controls: true,
        car_color: "#7b8792",
        ...config,
      };
      this._render();
    }

    _escape(value) {
      return String(value ?? "")
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#039;");
    }

    _emit(config) {
      this._config = config;
      this.dispatchEvent(
        new CustomEvent("config-changed", {
          detail: { config },
          bubbles: true,
          composed: true,
        }),
      );
      this._render();
    }

    _group(title, key, options) {
      const selected = Array.isArray(this._config[key]) ? this._config[key] : [];
      return `
        <section>
          <h4>${title}</h4>
          <div class="grid">
            ${options.map(([value, label]) => `
              <label>
                <input type="checkbox" data-list="${key}" data-value="${value}" ${selected.includes(value) ? "checked" : ""}>
                <span>${label}</span>
              </label>
            `).join("")}
          </div>
        </section>
      `;
    }

    _render() {
      if (!this.shadowRoot) return;
      this.shadowRoot.innerHTML = `
        <style>
          :host{display:block}
          .editor{display:grid;gap:15px;padding:4px 0 12px}
          section{display:grid;gap:7px}
          h4{margin:0;font-size:14px}
          .row{display:grid;grid-template-columns:1fr auto;gap:12px;align-items:end}
          .field{display:grid;gap:6px;font-size:12px;color:var(--secondary-text-color)}
          input[type=text]{min-height:40px;border:1px solid var(--divider-color);border-radius:8px;background:var(--card-background-color);color:var(--primary-text-color);padding:0 10px}
          .grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px 14px}
          .grid label,.check{display:flex;align-items:center;gap:8px;min-height:30px;font-size:13px}
          .note{padding:10px 12px;border-radius:10px;background:color-mix(in srgb,var(--primary-color) 7%,transparent);font-size:12px;color:var(--secondary-text-color);line-height:1.5}
          @media(max-width:520px){.grid{grid-template-columns:1fr}}
        </style>
        <div class="editor">
          <div class="row">
            <label class="field">Название
              <input id="title" type="text" value="${this._escape(this._config.title || "")}" placeholder="автомобиля GWM">
            </label>

          </div>
          <label class="check"><input id="dark" type="checkbox" ${this._config.dark === true ? "checked" : ""}>Тёмное оформление (иначе — тема Home Assistant)</label>
          <label class="check"><input id="confirm" type="checkbox" ${this._config.confirm_controls !== false ? "checked" : ""}>Подтверждать удалённые команды</label>
          ${this._group("Кнопки управления", "controls", CONTROL_OPTIONS)}
          ${this._group("Дополнительная информация", "info", INFO_OPTIONS)}
          ${this._group("Статусные плитки", "statuses", STATUS_OPTIONS)}
          <div class="note">
            Оформление StarLine: подсветка закрытого замка, анимация двигателя, индикация дверей и багажника.
            Команды и данные автомобиля предоставляет интеграция GWM RU.
          </div>
        </div>
      `;

      this.shadowRoot.querySelectorAll("[data-list]").forEach((element) => {
        element.addEventListener("change", () => {
          const key = element.dataset.list;
          const value = element.dataset.value;
          const current = [...(this._config[key] || [])];
          this._emit({
            ...this._config,
            [key]: element.checked
              ? (current.includes(value) ? current : [...current, value])
              : current.filter((item) => item !== value),
          });
        });
      });

      this.shadowRoot.getElementById("confirm")?.addEventListener("change", (event) =>
        this._emit({ ...this._config, confirm_controls: event.target.checked }),
      );

      this.shadowRoot.getElementById("title")?.addEventListener("change", (event) => {
        const next = { ...this._config };
        const value = String(event.target.value || "").trim();
        if (value) next.title = value;
        else delete next.title;
        this._emit(next);
      });

      this.shadowRoot.getElementById("dark")?.addEventListener("change", (event) =>
        this._emit({ ...this._config, dark: event.target.checked ? true : undefined }),
      );
    }
  }

  class GwmVehicleRemoteCard extends HTMLElement {
    constructor() {
      super();
      this.attachShadow({ mode: "open" });
      this.shadowRoot.addEventListener("click", (event) => {
        const button = event.target.closest?.("button[data-action]");
        if (button && !button.disabled) this._handleAction(button.dataset.action);
      });
      this._config = {};
      this._hass = null;
      this._entities = {};
      this._device = null;
      this._resolving = false;
      this._resolvedKey = null;
      this._busy = new Set();
      this._assumed = {};
    }

    static getStubConfig() {
      return {
        controls: [...DEFAULT_CONTROLS],
        info: [...DEFAULT_INFO],
        statuses: [...DEFAULT_STATUSES],
      };
    }

    static getConfigElement() {
      return document.createElement("gwm-vehicle-remote-card-editor");
    }

    static getGridOptions() {
      return { columns: 12, rows: 9, min_columns: 6, min_rows: 7 };
    }

    setConfig(config) {
      if ((config.device_id || "") !== (this._config.device_id || "") || (config.entity || "") !== (this._config.entity || "")) {
        this._entryId = undefined;
        this._entities = {};
      }
      this._config = {
        controls: [...DEFAULT_CONTROLS],
        info: [...DEFAULT_INFO],
        statuses: [...DEFAULT_STATUSES],
        confirm_controls: true,
        car_color: "#7b8792",
        ...config,
      };
      this._resolvedKey = null;
      if (this._hass) this._resolveEntities();
      this._render();
    }

    set hass(hass) {
      if (this._hass?.connection !== hass?.connection) this._resolvedKey = null;
      this._hass = hass;
      const key = `${this._config.device_id || ""}|${this._config.entity || ""}`;
      if (this._resolvedKey !== key && !this._resolving && !this._resolveRetryTimer) this._resolveEntities();
      this._render();
    }

    getCardSize() {
      return 9;
    }

    _awaitResponse(promise, milliseconds = 15000) {
      let timer;
      return Promise.race([promise, new Promise((_, reject) => {
        timer = setTimeout(() => reject(new Error("Home Assistant не ответил вовремя. Обновите данные перед повторной командой: её результат может быть неизвестен.")), milliseconds);
      })]).finally(() => clearTimeout(timer));
    }

    disconnectedCallback() {
      clearTimeout(this._resolveRetryTimer);
      this._resolveRetryTimer = null;
    }

    async _resolveEntities() {
      if (!this._hass || this._resolving) return;
      clearTimeout(this._resolveRetryTimer);
      this._resolveRetryTimer = null;
      this._resolving = true;
      const config = {...this._config};
      const resolveKey = `${config.device_id || ""}|${config.entity || ""}`;
      try {
        const registry = await this._awaitResponse(this._hass.callWS({ type: "config/entity_registry/list" }));
        let deviceId = config.device_id || null;

        if (!deviceId && config.entity) {
          deviceId = registry.find((entry) => entry.entity_id === config.entity)?.device_id || null;
        }

        const gwmEntries = registry.filter(
          (entry) => entry.platform === INTEGRATION || this._isGwmUniqueId(entry.unique_id),
        );

        if (!deviceId) deviceId = gwmEntries.find((entry) => entry.device_id)?.device_id || null;
        const entries = deviceId ? gwmEntries.filter((entry) => entry.device_id === deviceId) : gwmEntries;

        const devices = await this._awaitResponse(this._hass.callWS({ type: "config/device_registry/list" }));
        if (resolveKey !== `${this._config.device_id || ""}|${this._config.entity || ""}`) return;
        if (!Array.isArray(devices)) throw new Error("Реестр устройств Home Assistant недоступен");
        this._device = devices.find((device) => device.id === deviceId) || null;
        this._entryId = entries.find(entry => entry.config_entry_id)?.config_entry_id;
        this._entities = {};

        for (const [key, suffix] of Object.entries(SUFFIX)) {
          const found = entries.find((entry) => String(entry.unique_id || "").endsWith(suffix));
          if (found) this._entities[key] = found.entity_id;
        }

        this._entities.climate ||= entries.find((entry) => entry.entity_id.startsWith("climate."))?.entity_id;
        this._entities.lock ||= entries.find((entry) => entry.entity_id.startsWith("lock."))?.entity_id;
        this._entities.refresh ||= entries.find(
          (entry) => entry.entity_id.startsWith("button.") && /refresh|obnov/i.test(entry.entity_id),
        )?.entity_id;

        if (!this._entryId || !Object.keys(this._entities).length) throw new Error("Автомобиль пока не найден в Home Assistant");
        this._resolvedKey = resolveKey;
      } catch (error) {
        console.error("[GWM RU Remote Card] entity discovery failed", error);
      } finally {
        this._resolving = false;
        if (this._resolvedKey !== `${this._config.device_id || ""}|${this._config.entity || ""}`) {
          this._resolveRetryTimer = setTimeout(() => { this._resolveRetryTimer = null; if (this.isConnected) this._resolveEntities(); }, 10000);
        }
        this._render();
      }
    }

    _isGwmUniqueId(uniqueId) {
      return uniqueId && Object.values(SUFFIX).some((suffix) => String(uniqueId).endsWith(suffix));
    }

    _state(key) {
      const entityId = this._entities[key];
      return entityId ? this._hass?.states?.[entityId] : undefined;
    }

    _isOn(key) {
      return this._state(key)?.state === "on";
    }

    _isUnavailable(key) {
      const state = this._state(key)?.state;
      return !state || state === "unknown" || state === "unavailable";
    }

    _raw(key) {
      const state = this._state(key)?.state;
      return !state || ["unknown", "unavailable"].includes(state) ? null : String(state);
    }

    _value(key, fallback = "Нет данных") {
      const state = this._state(key);
      if (!state || ["unknown", "unavailable", ""].includes(state.state)) return fallback;
      const unit = state.attributes?.unit_of_measurement;
      return `${state.state}${unit ? ` ${unit}` : ""}`;
    }

    _icon(icon) {
      return `<ha-icon icon="${icon}"></ha-icon>`;
    }

    _escape(value) {
      return String(value ?? "")
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#039;");
    }

    _featureEnabled(key) {
      const flags = this._state("featureFlags");
      return !flags?.attributes || !(key in flags.attributes) || flags.attributes[key] !== false;
    }

    _remoteBusy() {
      return this._state("lastCommand")?.attributes?.in_progress === true;
    }

    _drivetrain() {
      const raw = (this._raw("modelCode") || "").toUpperCase();
      if (raw.includes("CC7150BA24C")) return "4WD";
      if (raw.includes("CC7150BA00B") || raw.includes("CC7150BA01B")) return "2WD";
      return null;
    }

    _title() {
      if (this._config.title) return String(this._config.title);
      const model = String(this._device?.model || "автомобиля GWM").trim();
      const drivetrain = this._drivetrain();
      return drivetrain ? `${model} ${drivetrain}` : model;
    }

    _relativeUpdate() {
      const raw = this._raw("lastUpdate");
      if (!raw) return "нет данных";
      const time = new Date(raw).getTime();
      if (!Number.isFinite(time)) return "нет данных";
      const seconds = Math.max(0, Math.round((Date.now() - time) / 1000));
      if (seconds < 60) return `${seconds} сек назад`;
      const minutes = Math.floor(seconds / 60);
      if (minutes < 60) return `${minutes} мин назад`;
      const hours = Math.floor(minutes / 60);
      return hours < 24 ? `${hours} ч назад` : `${Math.floor(hours / 24)} дн назад`;
    }

    _climateOn() {
      const climate = this._state("climate");
      return this._isOn("climateOn") || ["heat_cool", "heat", "cool", "fan_only"].includes(climate?.state);
    }

    _doorState(key) {
      return !this._isUnavailable(key) && this._isOn(key);
    }

    _doorStates() {
      return {
        fl: this._doorState("doorFl"),
        fr: this._doorState("doorFr"),
        rl: this._doorState("doorRl"),
        rr: this._doorState("doorRr"),
      };
    }

    _doorCount() {
      const keys = ["doorFl", "doorFr", "doorRl", "doorRr"];
      const available = keys.filter((key) => !this._isUnavailable(key));
      if (!available.length) return null;
      return available.filter((key) => this._isOn(key)).length;
    }

    _signalBars() {
      const raw = Number(this._raw("signal"));
      const known = Number.isFinite(raw);
      return `
        <span class="signal-bars" aria-label="GSM ${known ? `${raw} из 4` : "нет данных"}">
          ${[1, 2, 3, 4].map((index) =>
            `<i class="${known && index <= raw ? "on" : ""}" style="height:${8 + index * 4}px"></i>`
          ).join("")}
        </span>
      `;
    }

    _carSvg() {
      const dark = this._config.dark ?? this._hass?.themes?.darkMode ?? false;
      const img = (name, x, y, width, height, extra = "") =>
        `<image href="${STARLINE_ASSETS[name + (dark ? "_dark" : "")]}" x="${x}" y="${y}" width="${width}" height="${height}" ${extra}/>`;
      const locked = !this._isUnavailable("unlocked") && !this._isOn("unlocked");
      const doors = this._isOn("doors") || ["doorFl", "doorFr", "doorRl", "doorRr"].some(key => this._isOn(key));
      const engine = this._isOn("engine");
      const trunk = this._isOn("trunk");
      return `<svg class="starline-car" viewBox="-8 -8 350 220" role="img" aria-label="Автомобиль: двери — ${this._escape(this._doorSummary())}; двигатель — ${this._isUnavailable("engine") ? "нет данных" : engine ? "работает" : "выключен"}">
        <g class="security" opacity="${locked ? 1 : 0}">
          ${img("sectors_1",0,86,39,112)}${img("sectors_2",22,11,93,84)}${img("sectors_3",110,0,114,29)}
          <g transform="translate(333 0) scale(-1 1)">${img("sectors_1",0,86,39,112)}${img("sectors_2",22,11,93,84)}</g>
        </g>
        <g transform="translate(24 67)">
          ${img("bg_guard",63,19,158,113)}${img("hood",90,53,103,23)}
          ${img("door",15,28,63,91,`class="door-indicator" opacity="${doors ? 1 : 0}"`)}
          ${img("trunk",78,0,128,32,`class="trunk-indicator" opacity="${trunk ? 1 : 0}"`)}
          ${img("frontlight",73,79,27,15)}
          <g transform="translate(210 0) scale(-1 1)">${img("frontlight",0,79,27,15)}</g>
          ${img("key",117,30,54,22,`opacity="${engine ? 1 : 0}"`)}
          <g class="exhaust" opacity="${engine ? 1 : 0}">
            ${[1,2,3].map(n => img("smoke_"+n,222,22,39,85,`class="smoke smoke-${n}"`)).join("")}
          </g>
        </g>
        <g class="climate-indicator" opacity="${this._climateOn() ? 1 : 0}" transform="translate(166 180)">
          <g class="fan"><path d="M0 0 C-18 -25 16 -27 0 0 C28 -10 27 22 0 0 C-10 28 -30 6 0 0" fill="currentColor"/></g>
        </g>
      </svg>`;
    }

    _doorSummary() {
      const count = this._doorCount();
      if (count === null) {
        if (this._isUnavailable("doors")) return "Нет данных";
        return this._isOn("doors") ? "Есть открытые" : "Закрыты";
      }
      return count === 0 ? "Закрыты" : `${count} ${count === 1 ? "открыта" : "открыты"}`;
    }

    _statusMeta(id) {
      const engine = this._isOn("engine");
      const climate = this._climateOn();
      const windows = this._isOn("windows");
      const trunk = this._isOn("trunk");
      const unlocked = this._isOn("unlocked");
      const defrost = !this._isUnavailable("rearDefrost") && this._isOn("rearDefrost");
      const unknown = (key) => this._isUnavailable(key);

      return {
        engine: [
          "mdi:engine",
          "Двигатель",
          unknown("engine") ? "Нет данных" : engine ? "Работает" : "Выключен",
          engine ? "engine" : "ok",
        ],
        climate: [
          "mdi:fan",
          "Климат",
          !this._state("climate") && unknown("climateOn") ? "Нет данных" : climate ? "Включён" : "Выключен",
          climate ? "climate" : "ok",
        ],
        fuel: ["mdi:fuel", "Топливо", this._value("fuel", "Нет данных"), "info"],
        mileage: ["mdi:counter", "Пробег", this._value("mileage", "Нет данных"), "info"],
        doors: ["mdi:car-door", "Двери", this._doorSummary(), this._isOn("doors") ? "warn" : "ok"],
        windows: [
          "mdi:car-door",
          "Окна",
          unknown("windows") ? "Нет данных" : windows ? "Открыты" : "Закрыты",
          windows ? "warn" : "ok",
        ],
        trunk: [
          "mdi:car-back",
          "Багажник",
          unknown("trunk") ? "Нет данных" : trunk ? "Открыт" : "Закрыт",
          trunk ? "warn" : "ok",
        ],
        lock: [
          unlocked ? "mdi:lock-open-variant" : "mdi:lock",
          "Замок",
          unknown("unlocked") ? "Нет данных" : unlocked ? "Разблокирован" : "Закрыт",
          unlocked ? "unlock" : "lock",
        ],
        defrost: [
          "mdi:car-defrost-rear",
          "Defrost",
          this._isUnavailable("rearDefrost") ? "Нет данных" : defrost ? "Включён" : "Выключен",
          defrost ? "climate" : "ok",
        ],
      }[id] || null;
    }

    _renderStatuses() {
      const selected = Array.isArray(this._config.statuses) ? this._config.statuses : DEFAULT_STATUSES;
      return `
        <div class="status-dock">
          ${selected.map((id) => {
            const meta = this._statusMeta(id);
            return meta ? `
              <div class="status-tile ${meta[3]}" data-status="${id}">
                <span class="status-icon">${this._icon(meta[0])}</span>
                <span class="status-copy">
                  <small>${this._escape(meta[1])}</small>
                  <strong>${this._escape(meta[2])}</strong>
                </span>
              </div>
            ` : "";
          }).join("")}
        </div>
      `;
    }

    _infoMeta(id) {
      const pressures = ["tireFlP", "tireFrP", "tireRlP", "tireRrP"]
        .map((key) => this._raw(key))
        .filter(Boolean);

      return {
        fuel: ["mdi:fuel", "Топливо", this._value("fuel")],
        range: ["mdi:map-marker-distance", "Запас хода", this._value("range")],
        mileage: ["mdi:counter", "Пробег", this._value("mileage")],
        tires: ["mdi:car-tire-alert", "Шины", pressures.length ? pressures.join(" / ") : "Нет данных"],
        gsm: ["mdi:signal", "GSM", `${this._raw("signal") ?? "—"}/4`],
        gps: ["mdi:crosshairs-gps", "GPS", this._isUnavailable("gps") ? "Нет данных" : this._isOn("gps") ? "есть" : "нет"],
        climate: ["mdi:air-conditioner", "Климат", this._climateOn() ? "работает" : "выключен"],
        oil: ["mdi:oil", "Масло", this._raw("oilQty") === null ? "Нет данных" : `${this._raw("oilQty")}/8`],
        update: ["mdi:cloud-sync", "Обновление", this._relativeUpdate()],
      }[id] || null;
    }

    _renderInfo() {
      const selected = Array.isArray(this._config.info) ? this._config.info : DEFAULT_INFO;
      const items = selected.map((id) => this._infoMeta(id)).filter(Boolean);
      return items.length ? `
        <div class="info-grid">
          ${items.map((meta) => `
            <div class="info-tile">
              ${this._icon(meta[0])}
              <div>
                <small>${this._escape(meta[1])}</small>
                <strong>${this._escape(meta[2])}</strong>
              </div>
            </div>
          `).join("")}
        </div>
      ` : "";
    }

    _controlMeta(id) {
      if (id === "seat_heating") {
        if (!this._featureEnabled("seat_heat_driver") || !this._featureEnabled("seat_heat_passenger")) return null;
        const levels = ["seatDriver", "seatPassenger"].map(key => this._isUnavailable(key) ? null : Number(this._state(key)?.state));
        const on = levels.some(v => v > 0);
        const known = levels.every(v => Number.isInteger(v) && v >= 0 && v <= 3);
        return ["mdi:car-seat-heater", known ? (on ? "Сиденья вкл" : "Сиденья выкл") : "Сиденья · нет данных", on ? "active" : "", !this._entryId || !known];
      }
      const feature = FEATURE_BY_CONTROL[id];
      if (feature && !this._featureEnabled(feature)) return null;

      const unlocked = this._isOn("unlocked");
      const engine = this._isOn("engine");
      const climate = this._climateOn();
      const trunk = this._isOn("trunk");
      const windows = this._isOn("windows");
      const steering = !this._isUnavailable("steeringHeat") ? this._isOn("steeringHeat") : Boolean(this._assumed.steeringHeat);
      const rear = !this._isUnavailable("rearDefrost") ? this._isOn("rearDefrost") : Boolean(this._assumed.rearDefrost);
      const front = !this._isUnavailable("frontDefrost") ? this._isOn("frontDefrost") : Boolean(this._assumed.frontDefrost);

      return {
        lock: [
          unlocked ? "mdi:lock" : "mdi:lock-open-variant",
          unlocked ? "Закрыть" : "Открыть",
          !this._isUnavailable("unlocked") && !unlocked ? "active" : "",
          this._isUnavailable("unlocked"),
        ],
        engine: [
          engine ? "mdi:engine-off" : "mdi:engine",
          engine ? "Заглушить" : "Запустить",
          engine ? "active" : "",
          this._isUnavailable("engine"),
        ],
        climate: ["mdi:air-conditioner", climate ? "Климат выкл." : "Климат вкл.", climate ? "active climate" : "", false],
        trunk: ["mdi:car-back", trunk ? "Закрыть багажник" : "Открыть багажник", trunk ? "warn" : "", this._isUnavailable("trunk")],
        windows: ["mdi:car-door", windows ? "Закрыть окна" : "Открыть окна", windows ? "warn" : "", this._isUnavailable("windows")],
        refresh: ["mdi:refresh", "Обновить", "", false],
        steering: ["mdi:steering", steering ? "Руль выкл." : "Руль вкл.", steering ? "active" : "", false],
        rear_defrost: ["mdi:car-defrost-rear", rear ? "Заднее выкл." : "Defrost вкл.", rear ? "active" : "", false],
        front_defrost: ["mdi:car-defrost-front", front ? "Defrost выкл." : "Defrost вкл.", front ? "active" : "experimental", false],
        sunroof: ["mdi:car-select", "Панорама", "experimental", false],
        sunshade: ["mdi:blinds", "Шторка", "experimental", false],
      }[id] || null;
    }

    _renderControls() {
      const selected = Array.isArray(this._config.controls) ? this._config.controls : DEFAULT_CONTROLS;
      const remoteBusy = this._remoteBusy();
      const items = selected.map((id) => {
        const meta = this._controlMeta(id);
        if (!meta) return "";
        const busy = this._busy.has(id) || (remoteBusy && id !== "refresh");
        const disabled = meta[3] || busy;
        return `
          <button class="remote-action ${meta[2]} ${busy ? "busy" : ""}" ${disabled ? "disabled" : `data-action="${id}"`}>
            <span class="action-circle">${this._icon(meta[0])}</span>
            <span>${this._escape(meta[1])}${meta[4] ? `<small style="display:block;font-size:11px;margin-top:4px">${this._escape(meta[4])}</small>` : ""}</span>
          </button>
        `;
      }).join("");
      return items ? `<div class="remote-controls">${items}</div>` : "";
    }

    _render() {
      if (!this.shadowRoot) return;
      if (!this._hass) {
        this.shadowRoot.innerHTML = `<ha-card><div style="padding:20px">GWM RU Remote Card</div></ha-card>`;
        return;
      }

      const onlineKnown = !this._isUnavailable("tbox");
      const online = onlineKnown && this._isOn("tbox");

      const markup = `
        <style>
          :host{display:block;--gwm-text:var(--primary-text-color,#212121);--gwm-muted:var(--secondary-text-color,#727272);--gwm-accent:#00aeef;--gwm-ring:#b0c80c}
          *{box-sizing:border-box}
          ha-card{display:block;overflow:hidden;background:var(--ha-card-background,var(--card-background-color,#fff));color:var(--gwm-text)}
          .wrap{padding:20px 20px 16px;container-type:inline-size}
          .hero{position:relative;text-align:center}
          .vehicle-name{font-size:20px;line-height:28px;font-weight:500;text-align:left;padding-right:95px;overflow-wrap:anywhere}
          .connection-card{position:absolute;right:0;top:0;color:var(--gwm-muted);font-size:11px}
          .online-line,.gsm-line{display:flex;align-items:center;justify-content:flex-end;gap:6px}
          .gsm-line{margin-top:5px}.dot{width:6px;height:6px;border-radius:50%;background:#9e9e9e}
          .online .dot{background:#b0c80c}.offline .dot{background:#e75b51}
          .signal-bars{display:flex;align-items:flex-end;gap:2px;height:16px;transform:scale(.65);transform-origin:right center}
          .signal-bars i{display:block;width:4px;background:var(--divider-color,#ddd)}.signal-bars i.on{background:var(--gwm-accent)}
          .starline-car{display:block;width:min(100%,350px);height:auto;margin:12px auto 0;color:var(--gwm-accent)}
          .security,.door-indicator,.trunk-indicator,.exhaust,.climate-indicator{transition:opacity .25s linear}
          .smoke{animation:smoke 1.5s steps(1,end) infinite;opacity:0}.smoke-2{animation-delay:-1s}.smoke-3{animation-delay:-.5s}
          .exhaust[opacity="0"] .smoke,.climate-indicator[opacity="0"] .fan{animation:none}
          .fan{animation:fanSpin 2s linear infinite}
          @keyframes smoke{0%,100%{opacity:1}33.333%,99.999%{opacity:0}}
          @keyframes fanSpin{to{transform:rotate(360deg)}}
          @keyframes blink{0%,100%{opacity:1}50%{opacity:0}}
          .remote-controls{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));align-items:center;gap:16px 8px;max-width:350px;margin:12px auto 22px}
          .remote-action{appearance:none;border:0;background:none;color:var(--gwm-text);font:inherit;cursor:pointer;display:flex;flex-direction:column;align-items:center;gap:8px;min-width:0;padding:0}
          .action-circle{display:grid;place-items:center;width:76px;height:76px;border:3px solid var(--gwm-ring);border-radius:50%;background:var(--card-background-color,#fff);color:#00aeef;transition:background .2s,box-shadow .2s,transform .2s}
          .remote-action:nth-child(2) .action-circle{width:94px;height:94px}
          .remote-action:nth-child(n+4) .action-circle{width:48px;height:48px;border-width:2px}
          .action-circle ha-icon{--mdc-icon-size:38px}.remote-action:nth-child(n+4) ha-icon{--mdc-icon-size:24px}
          .remote-action>span:last-child{font-size:11px;line-height:15px;text-align:center;overflow-wrap:anywhere}
          .remote-action.active .action-circle{background:#b0c80c;color:#fff}.remote-action.warn .action-circle{border-color:#ef8b32}
          .remote-action:disabled{cursor:default;opacity:.45}.remote-action.busy .action-circle{animation:blink 1.2s linear infinite}
          .remote-action:not(:disabled):hover .action-circle{transform:translateY(-2px)}.remote-action:not(:disabled):active .action-circle{transform:scale(.95)}
          .remote-action:focus-visible{outline:2px solid var(--gwm-accent);outline-offset:4px;border-radius:12px}
          .status-dock{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px 10px;border-top:1px solid var(--divider-color,#ddd);padding-top:16px}
          .status-tile{display:flex;flex-direction:column;align-items:center;gap:5px;text-align:center;min-width:0}
          .status-icon{color:var(--gwm-accent)}.status-icon ha-icon{--mdc-icon-size:23px}
          .status-copy{display:grid;gap:3px}.status-copy small,.info-tile small{font-size:10px;color:var(--gwm-muted)}
          .status-copy strong,.info-tile strong{font-size:12px;font-weight:500;line-height:17px;white-space:normal;overflow:visible;overflow-wrap:anywhere}
          .status-tile.warn .status-icon,.status-tile.unlock .status-icon{color:#ef8b32}.status-tile.climate .status-icon ha-icon{animation:fanSpin 2s linear infinite}
          .info-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin-top:18px;padding-top:14px;border-top:1px solid var(--divider-color,#ddd)}
          .info-tile{display:flex;align-items:center;gap:10px;min-width:0;color:var(--gwm-accent)}.info-tile>div{display:grid;gap:3px;color:var(--gwm-text)}
          ha-card.dark{--gwm-text:#fff;--gwm-muted:#a5adb4;--gwm-ring:#000;--divider-color:#39444d;background:#1c252d}
          .dark .action-circle{border:4px solid #000;background:linear-gradient(to bottom,#3c4042 0%,#141c22 100%);box-shadow:inset 0 2px 1px #5d5d5d;color:#fff}
          .dark .remote-action.active .action-circle{background:linear-gradient(to bottom,#3c4042 0%,#141c22 100%);box-shadow:inset 0 2px 1px #6ecaf1,inset 0 0 0 5px #2bafe5}
          @container(max-width:300px){.action-circle{width:62px;height:62px}.remote-action:nth-child(2) .action-circle{width:78px;height:78px}.status-dock{grid-template-columns:repeat(2,minmax(0,1fr))}}
          @media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important}.smoke{opacity:0}.smoke-1{opacity:1}}
        </style>

        <ha-card class="${(this._config.dark ?? this._hass?.themes?.darkMode ?? false) ? "dark" : "light"}">
          <div class="wrap">
            <div class="hero">
              <div class="vehicle-name">${this._escape(this._title())}</div>
              <div class="connection-card ${onlineKnown ? (online ? "online" : "offline") : "unknown"}">
                <div class="online-line">
                  <span class="dot"></span>
                  <span>${onlineKnown ? (online ? "Онлайн" : "Оффлайн") : "Нет данных"}</span>
                </div>
                <div class="gsm-line">
                  <span>GSM</span>
                  ${this._signalBars()}
                </div>
              </div>
              ${this._carSvg()}
            </div>

            ${this._renderControls()}
            ${this._renderStatuses()}
            ${this._renderInfo()}
          </div>
        </ha-card>
      `;

      // Preserve focus and animation progress across Home Assistant updates.
      const template = document.createElement("template");
      template.innerHTML = markup;
      this._syncDom(this.shadowRoot, template.content);
    }

    _syncDom(current, next) {
      const oldNodes = [...current.childNodes], newNodes = [...next.childNodes];
      for (let i = 0; i < Math.max(oldNodes.length, newNodes.length); i++) {
        const oldNode = oldNodes[i], newNode = newNodes[i];
        if (!newNode) { oldNode.remove(); continue; }
        if (!oldNode) { current.append(newNode.cloneNode(true)); continue; }
        if (oldNode.nodeType !== newNode.nodeType || oldNode.nodeName !== newNode.nodeName) {
          oldNode.replaceWith(newNode.cloneNode(true)); continue;
        }
        if (oldNode.nodeType !== Node.ELEMENT_NODE) {
          if (oldNode.textContent !== newNode.textContent) oldNode.textContent = newNode.textContent;
          continue;
        }
        for (const attr of [...oldNode.attributes]) {
          if (!newNode.hasAttribute(attr.name)) oldNode.removeAttribute(attr.name);
        }
        for (const attr of [...newNode.attributes]) {
          if (oldNode.getAttribute(attr.name) !== attr.value) oldNode.setAttribute(attr.name, attr.value);
        }
        // HA icons own their rendered content; the card's light DOM is ours.
        if (oldNode.localName !== "ha-icon") this._syncDom(oldNode, newNode);
      }
    }

    _confirm(message) {
      return this._config.confirm_controls === false || window.confirm(message);
    }

    async _runBusy(key, fn, onSuccess = null) {
      if (this._busy.has(key)) return;
      this._busy.add(key);
      this._render();
      try {
        await this._awaitResponse(Promise.resolve().then(fn), key === "profiles" ? 30000 : key === "refresh" ? 150000 : 600000);
        if (onSuccess) onSuccess();
      } catch (error) {
        console.error(`[GWM RU Remote Card] ${key} failed`, error);
        alert(`GWM RU: ${error?.message || String(error)}`);
      } finally {
        this._busy.delete(key);
        this._render();
      }
    }

    async _handleAction(action) {
      if (!this._hass) return;

      const unlocked = this._isOn("unlocked");
      const engine = this._isOn("engine");
      const climate = this._climateOn();
      const trunk = this._isOn("trunk");
      const windows = this._isOn("windows");

      if (action === "seat_heating") {
        if (!this._entryId || !this._featureEnabled("seat_heat_driver") || !this._featureEnabled("seat_heat_passenger")) return;
        if (["seatDriver", "seatPassenger"].some(key => this._isUnavailable(key))) return;
        const on = ["seatDriver", "seatPassenger"].some(key => Number(this._state(key)?.state) > 0);
        if (!this._confirm(on ? "Выключить оба подогрева?" : "Включить оба подогрева на уровень 3 на 10 минут?")) return;
        return this._runBusy(action, () => this._hass.callService(INTEGRATION, "set_seat_heating", {entry_id:this._entryId,driver:on ? 0 : 3,passenger:on ? 0 : 3,operation_time:10}));
      }
      if (action === "lock") {
        if (!this._confirm(unlocked ? "Закрыть автомобиль?" : "Разблокировать автомобиль?")) return;
        return this._runBusy(action, () =>
          this._hass.callService(INTEGRATION, unlocked ? "lock_vehicle" : "unlock_vehicle", { entry_id: this._entryId }),
        );
      }

      if (action === "engine") {
        if (!engine) {
          const blockers = [];
          if (unlocked) blockers.push("автомобиль не закрыт");
          if (this._isOn("doors")) blockers.push("открыта дверь");
          if (trunk) blockers.push("открыт багажник");
          if (blockers.length) return alert(`GWM RU: запуск недоступен — ${blockers.join(", ")}.`);
        }
        if (!this._confirm(engine ? "Остановить двигатель?" : "Запустить двигатель на 15 минут?")) return;
        return this._runBusy(action, () =>
          this._hass.callService(INTEGRATION, engine ? "engine_stop" : "engine_start", engine ? {} : { operation_time: 15 }),
        );
      }

      if (action === "climate") {
        const entityId = this._entities.climate;
        if (!entityId) return alert("GWM RU: сущность климата не найдена");
        if (!this._confirm(climate ? "Выключить климат?" : "Включить климат? На автомобиле с ДВС может запуститься двигатель.")) return;
        return this._runBusy(action, () =>
          this._hass.callService("climate", climate ? "turn_off" : "turn_on", { entity_id: entityId }),
        );
      }

      if (action === "trunk") {
        if (!this._confirm(trunk ? "Закрыть багажник?" : "Открыть багажник?")) return;
        return this._runBusy(action, () =>
          this._hass.callService(INTEGRATION, trunk ? "close_trunk" : "open_trunk", {}),
        );
      }

      if (action === "windows") {
        if (!this._confirm(windows ? "Закрыть все окна?" : "Открыть все окна? Команда открытия экспериментальная.")) return;
        return this._runBusy(action, () =>
          this._hass.callService(INTEGRATION, windows ? "close_windows" : "open_windows", {}),
        );
      }

      if (action === "refresh") {
        const entityId = this._entities.refresh;
        if (!entityId) return alert("GWM RU: кнопка обновления не найдена");
        return this._runBusy(action, () =>
          this._hass.callService("button", "press", { entity_id: entityId }),
        );
      }

      if (action === "steering") {
        return this._toggleComfort(
          action,
          "steeringHeat",
          "steering_wheel_heat_on",
          "steering_wheel_heat_off",
          "обогрев руля",
        );
      }

      if (action === "rear_defrost") {
        return this._toggleComfort(
          action,
          "rearDefrost",
          "rear_defrost_on",
          "rear_defrost_off",
          "обогрев заднего стекла",
        );
      }

      if (action === "front_defrost") {
        return this._toggleComfort(
          action,
          "frontDefrost",
          "front_defrost_on",
          "front_defrost_off",
          "передний defrost",
        );
      }

      if (action === "sunroof") {
        return this._toggleRoof(action, "sunroofOpen", "open_sunroof", "close_sunroof", "панораму");
      }

      if (action === "sunshade") {
        return this._toggleRoof(action, "sunshadeOpen", "open_sunshade", "close_sunshade", "шторку");
      }
    }

    async _toggleComfort(action, key, onService, offService, label) {
      const current = !this._isUnavailable(key) ? this._isOn(key) : Boolean(this._assumed[key]);
      const next = !current;
      if (!this._confirm(`${next ? "Включить" : "Выключить"} ${label}?`)) return;
      return this._runBusy(
        action,
        () => this._hass.callService(INTEGRATION, next ? onService : offService, {}),
        () => { this._assumed[key] = next; },
      );
    }

    async _toggleRoof(action, key, openService, closeService, label) {
      let current = this._assumed[key];
      if (current === undefined) {
        const open = window.confirm(`${label[0].toUpperCase()}${label.slice(1)}: ОК — открыть, Отмена — закрыть.`);
        current = !open;
      }
      const next = !current;
      if (this._config.confirm_controls !== false && !this._confirm(`${next ? "Открыть" : "Закрыть"} ${label}?`)) return;
      return this._runBusy(
        action,
        () => this._hass.callService(INTEGRATION, next ? openService : closeService, {}),
        () => { this._assumed[key] = next; },
      );
    }
  }

  if (!customElements.get("gwm-vehicle-remote-card-editor")) {
    customElements.define("gwm-vehicle-remote-card-editor", GwmVehicleRemoteCardEditor);
  }

  if (!customElements.get("gwm-vehicle-remote-card")) {
    customElements.define("gwm-vehicle-remote-card", GwmVehicleRemoteCard);
  }

  window.customCards = window.customCards || [];
  if (!window.customCards.some((card) => card.type === "gwm-vehicle-remote-card")) {
    window.customCards.push({
      type: "gwm-vehicle-remote-card",
      name: "GWM RU — анимированный пульт",
      description: "Широкий top-view автомобиля с крупными статусами, значениями топлива/пробега и независимой анимацией дверей, багажника, двигателя и климата",
      preview: true,
      documentationURL: "https://github.com/roblencheg/HAVAL_H3",
    });
  }

  console.info(
    `%c GWM RU REMOTE CARD %c ${CARD_VERSION} `,
    "background:#0f1922;color:white;font-weight:bold;padding:2px 6px;border-radius:3px",
    "background:#526474;color:white;padding:2px 6px;border-radius:3px",
  );
})();
